    v_tr := null;
    select id into v_tr from public.transacciones_contables where localidad_id = v_loc and numero = r.transaccion::integer;
    -- Una partida registrada en el sistema (no migrada) con el mismo número o número anual no se toca: se informa.
    v_ex := null;
    select id, origen_anterior into v_ex from public.partidas where localidad_id = v_loc and ((anio = r.anio and mes = r.mes and numero = r.numero) or (anio = r.anio and numero_anual = r.anual))
      order by (anio = r.anio and mes = r.mes and numero = r.numero) desc limit 1;
    if v_ex.id is not null and v_ex.origen_anterior is distinct from 'MIGRADO' then
      p_s := p_s + 1; v_choques := array_append(v_choques, format('3-0%s %s-%s (anual %s)', r.loc, lpad(r.mes::text, 2, '0'), r.numero, r.anual)); continue;
    end if;
